--
-- Table structure for table `PRESTAMO`
--

DROP TABLE IF EXISTS `PRESTAMO`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PRESTAMO` (
  `id_prestamo` int NOT NULL AUTO_INCREMENT,
  `id_comprador` int NOT NULL,
  `id_publicacion` int NOT NULL,
  `fecha_solicitud` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `fecha_inicio` datetime DEFAULT NULL,
  `fecha_devolucion_pactada` datetime NOT NULL,
  `fecha_devolucion_real` datetime DEFAULT NULL,
  `estado_prestamo` varchar(15) NOT NULL DEFAULT 'Solicitado',
  PRIMARY KEY (`id_prestamo`),
  KEY `fk_prestamo_comp` (`id_comprador`),
  KEY `fk_prestamo_pub` (`id_publicacion`),
  CONSTRAINT `fk_prestamo_comp` FOREIGN KEY (`id_comprador`) REFERENCES `COMPRADOR` (`id_comprador`) ON DELETE RESTRICT,
  CONSTRAINT `fk_prestamo_pub` FOREIGN KEY (`id_publicacion`) REFERENCES `PUBLICACION` (`id_publicacion`) ON DELETE RESTRICT,
  CONSTRAINT `chk_est_prestamo` CHECK ((`estado_prestamo` in (_utf8mb4'Solicitado',_utf8mb4'Activo',_utf8mb4'Devuelto',_utf8mb4'Demorado'))),
  CONSTRAINT `chk_f_inicio` CHECK ((`fecha_inicio` > `fecha_solicitud`)),
  CONSTRAINT `chk_f_pactada` CHECK ((`fecha_devolucion_pactada` >= `fecha_inicio`)),
  CONSTRAINT `chk_f_real` CHECK ((`fecha_devolucion_real` >= `fecha_inicio`))
) ENGINE=InnoDB AUTO_INCREMENT=201 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

