--
-- Table structure for table `PRODUCTO`
--

DROP TABLE IF EXISTS `PRODUCTO`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PRODUCTO` (
  `id_producto` int NOT NULL AUTO_INCREMENT,
  `id_publicacion` int NOT NULL,
  `precio` decimal(15,2) NOT NULL,
  `calificacion` decimal(3,1) DEFAULT NULL,
  `estado_fisico` varchar(10) NOT NULL,
  `stock` int NOT NULL,
  PRIMARY KEY (`id_producto`),
  KEY `fk_prod_pub` (`id_publicacion`),
  CONSTRAINT `fk_prod_pub` FOREIGN KEY (`id_publicacion`) REFERENCES `PUBLICACION` (`id_publicacion`) ON DELETE CASCADE,
  CONSTRAINT `chk_estado_fisico` CHECK ((`estado_fisico` in (_utf8mb4'NUEVO',_utf8mb4'USADO'))),
  CONSTRAINT `chk_prod_calif` CHECK (((`calificacion` >= 0) and (`calificacion` <= 10))),
  CONSTRAINT `chk_prod_precio` CHECK ((`precio` > 0)),
  CONSTRAINT `chk_stock` CHECK ((`stock` >= 0))
) ENGINE=InnoDB AUTO_INCREMENT=491 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

