DROP TABLE IF EXISTS `PUBLICACION`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `PUBLICACION` (
  `id_publicacion` int NOT NULL AUTO_INCREMENT,
  `id_vendedor` int NOT NULL,
  `id_administrador_moderador` int DEFAULT NULL,
  `tipo_item` varchar(20) NOT NULL,
  `titulo` varchar(150) NOT NULL,
  `descripcion` text,
  `fecha_publicacion` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `estado_publicacion` varchar(20) NOT NULL DEFAULT 'Activa',
  PRIMARY KEY (`id_publicacion`),
  KEY `fk_pub_vendedor` (`id_vendedor`),
  KEY `fk_pub_admin` (`id_administrador_moderador`),
  CONSTRAINT `fk_pub_admin` FOREIGN KEY (`id_administrador_moderador`) REFERENCES `ADMINISTRADOR` (`id_administrador`) ON DELETE SET NULL,
  CONSTRAINT `fk_pub_vendedor` FOREIGN KEY (`id_vendedor`) REFERENCES `VENDEDOR` (`id_vendedor`) ON DELETE RESTRICT,
  CONSTRAINT `chk_estado_pub` CHECK ((`estado_publicacion` in (_utf8mb4'Activa',_utf8mb4'Pausada',_utf8mb4'Bloqueada',_utf8mb4'Finalizada'))),
  CONSTRAINT `chk_tipo_item` CHECK ((`tipo_item` in (_utf8mb4'Producto',_utf8mb4'Servicio')))
) ENGINE=InnoDB AUTO_INCREMENT=1001 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

