  CONSTRAINT `fk_trueque_comp` FOREIGN KEY (`id_comprador_iniciador`) REFERENCES `COMPRADOR` (`id_comprador`) ON DELETE RESTRICT,
  CONSTRAINT `fk_trueque_deseada` FOREIGN KEY (`id_publicacion_deseada`) REFERENCES `PUBLICACION` (`id_publicacion`) ON DELETE RESTRICT,
  CONSTRAINT `fk_trueque_ofrecida` FOREIGN KEY (`id_publicacion_ofrecida`) REFERENCES `PUBLICACION` (`id_publicacion`) ON DELETE RESTRICT,
  CONSTRAINT `chk_est_trueque` CHECK ((`estado_trueque` in (_utf8mb4'Pendiente',_utf8mb4'Aceptado',_utf8mb4'Rechazado'))),
  CONSTRAINT `chk_pub_distintas` CHECK ((`id_publicacion_ofrecida` <> `id_publicacion_deseada`))
) ENGINE=InnoDB AUTO_INCREMENT=81 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
