CREATE DEFINER=`root`@`localhost` FUNCTION `calcular_probabilidad_producto`(p_id_producto INT) RETURNS decimal(10,6)
    READS SQL DATA
BEGIN
    DECLARE v_vt INT DEFAULT 0;
    DECLARE v_c DECIMAL(10,4) DEFAULT 0.0000;
    DECLARE v_cm DECIMAL(10,4) DEFAULT 0.0000;
    DECLARE v_k DECIMAL(10,4) DEFAULT 10.0000;
    DECLARE v_fiabilidad DECIMAL(10,4) DEFAULT 0.0000;

    -- Unimos PRODUCTO con PUBLICACION y luego con VENDEDOR
    SELECT v.ventas_completadas, v.calificacion
    INTO v_vt, v_c
    FROM PRODUCTO p
    INNER JOIN PUBLICACION pub ON p.id_publicacion = pub.id_publicacion
    INNER JOIN VENDEDOR v ON pub.id_vendedor = v.id_vendedor
    WHERE p.id_producto = p_id_producto;

    -- Obtenemos la calificación promedio global de los vendedores
    SELECT AVG(calificacion)
    INTO v_cm
    FROM VENDEDOR;

    -- Aplicamos la fórmula de fiabilidad
    IF (v_vt + v_k) > 0 THEN
        SET v_fiabilidad =
            ((v_vt / (v_vt + v_k)) * v_c) +
            ((v_k / (v_vt + v_k)) * v_cm);
    ELSE
        SET v_fiabilidad = 0.0000;
    END IF;

    RETURN v_fiabilidad;
END ;;
DELIMITER ;
